// Reads the newest arrivals in a DSpace archive, page by page, until it
// reaches what earlier checks already saw. The source's address asks the API
// to sort by the day an item arrived, so the first older one means the rest
// are older too. Theseus files a thesis's publication date as the year only,
// which is why the arrival day is the date that counts.
//
// Only the record is read: title, abstract, subjects, university, licence.
// The thesis file itself is never fetched.
const src = $('Start').first().json;
const since = new Date($json.since);
const UA = 'DFP newsletter bot (HAMK student project)';
const MAX_PAGES = 20;               // 2,000 items, more than a busy week in May

const first = (md, key) => ((md[key] || [])[0] || {}).value || null;
const all = (md, key) => (md[key] || []).map(v => v.value).filter(Boolean);
const clean = s => String(s || '').replace(/\s+/g, ' ').trim();

// Some values come in three languages at once:
// "fi=AMK-opinnäytetyö|sv=YH-examensarbete|en=Bachelor's thesis|"
const finnish = value => {
  if (!value) return null;
  const parts = String(value).split('|').map(s => s.trim()).filter(Boolean);
  if (!parts.length) return null;
  const fi = parts.find(p => p.startsWith('fi='));
  return clean(fi ? fi.slice(3) : parts[0].replace(/^[a-z]{2}=/, '')) || null;
};

// The editors read Finnish, so where a thesis has its abstract in two
// languages the Finnish one is kept. Most abstracts carry no language mark,
// so the one with the most common Finnish words wins.
const FINNISH_WORDS = /(^|\s)(ja|on|oli|että|sekä|tämän|tavoitteena|opinnäytetyö\S*)(?=\s|[.,:;]|$)/gi;
function abstractOf(md) {
  const values = (md['dc.description.abstract'] || []).filter(v => clean(v.value));
  if (!values.length) return '';
  const marked = values.find(v => v.language === 'fi');
  if (marked) return clean(marked.value);
  const score = v => (String(v.value).match(FINNISH_WORDS) || []).length;
  return clean([...values].sort((a, b) => score(b) - score(a))[0].value);
}

function licence(md) {
  const value = first(md, 'dc.rights');
  if (!value) return null;
  return /all rights reserved/i.test(value) ? 'All rights reserved' : finnish(value);
}

const LANGUAGE = { fin: 'fi', eng: 'en', swe: 'sv' };

function toItem(it) {
  const md = it.metadata || {};
  const level = finnish(first(md, 'dc.type.ontasot'));
  const abstract = abstractOf(md);
  const code = first(md, 'dc.language.iso');
  return {
    url: first(md, 'dc.identifier.uri') || (it.handle ? `https://www.theseus.fi/handle/${it.handle}` : null),
    title: clean(first(md, 'dc.title')).replace(/ : /g, ': ') || null,
    published_at: first(md, 'dc.date.accessioned'),
    publisher: finnish(first(md, 'dc.contributor.organization')) || first(md, 'dc.publisher'),
    source_language: LANGUAGE[code] || (code ? code.slice(0, 2) : null),
    excerpt: abstract.slice(0, 300) || null,
    raw_text: abstract || null,
    subjects: all(md, 'dc.subject.yso').slice(0, 30),
    details: {
      kind: level ? 'thesis' : 'publication',
      level: level || finnish(first(md, 'dc.type.okm')),
      programme: finnish(first(md, 'dc.subject.degreeprogram')),
      licence: licence(md),
    },
  };
}

const records = [];
let pages = 0;
let error = null;
try {
  for (let page = 0; page < MAX_PAGES; page++) {
    const data = await this.helpers.httpRequest({
      url: `${src.url}&page=${page}`, json: true, timeout: 30000,
      headers: { 'User-Agent': UA, Accept: 'application/json' },
    });
    pages++;
    const result = (data._embedded || {}).searchResult || {};
    const objects = (result._embedded || {}).objects || [];
    let older = false;
    for (const o of objects) {
      const it = (o._embedded || {}).indexableObject;
      if (!it) continue;
      const arrived = first(it.metadata || {}, 'dc.date.accessioned');
      if (arrived && new Date(arrived) < since) { older = true; break; }
      records.push(toItem(it));
    }
    if (older || !objects.length || page + 1 >= ((result.page || {}).totalPages || 0)) break;
  }
} catch (e) {
  // What was read before the archive stopped answering is still stored.
  error = `the archive did not answer: ${e.message}`;
}
return [{ json: { records, pages, error } }];

// The ingest API takes 200 items a request, and the first check alone
// brings a week of theses, so they go in batches. With nothing new one empty
// batch still goes, so every run is reported the same way.
const src = $('Start').first().json;
const fresh = $json.items || [];
const batches = [];
for (let i = 0; i < fresh.length; i += 200) batches.push(fresh.slice(i, i + 200));
if (!batches.length) batches.push([]);
return batches.map(chunk => ({ json: { body: { items: chunk.map(a => ({
  source_id: Number(src.source_id),
  url: a.url,
  title: a.title,
  publisher: a.publisher || src.publisher || null,
  published_at: a.published_at,
  excerpt: a.excerpt || null,
  raw_text: a.raw_text || null,
  source_language: a.source_language || null,
  subjects: a.subjects || [],
  details: a.details || null,
})) } } }));

// What the schedule writes to collection_runs for this source.
const read = $('Read the archive').first().json;
const results = $input.all().flatMap(i => i.json.results || []);
const rejected = results.filter(r => !r.accepted);

const problems = [];
if (read.error) problems.push(read.error);
if (rejected.length) problems.push(`${rejected.length} rejected: ` +
  [...new Set(rejected.map(r => r.reason))].join(', '));

return [{ json: {
  items_found: read.records.length,
  items_new: results.filter(r => r.accepted && r.new).length,
  error: problems.length ? problems.join('; ') : null,
} }];
